import json, re
from pathlib import Path
PHOTO_BYTES = 5113544
AUDIO_BYTES = 25633
def normalized_type(value):
    return re.sub(r'[^a-z0-9/+.-]+', ' ', str(value).casefold()).strip()
def parse_size(value, target):
    if not isinstance(value, str):
        return False
    text = value.strip().casefold().replace(',', '')
    match = re.fullmatch(r'([0-9]+(?:\.[0-9]+)?)\s*(bytes?|b|kb|kib|mb|mib)', text)
    if not match:
        return False
    number_text, unit = match.groups()
    factors = {'b': 1, 'byte': 1, 'bytes': 1, 'kb': 1024, 'kib': 1024, 'mb': 1048576, 'mib': 1048576}
    shown = float(number_text) * factors[unit]
    decimals = len(number_text.partition('.')[2])
    rounding = 0.5 * (10 ** -decimals) * factors[unit]
    return abs(shown - target) <= max(1, rounding + 1)
try:
    data = json.loads(Path('/tmp/media/manifest.json').read_text(encoding='utf-8'))
    photo = data['photo']
    audio = data['audio']
    photo_type = normalized_type(photo.get('type', ''))
    audio_type = normalized_type(audio.get('type', ''))
    ok = (
        photo.get('filename') == 'incident_scene_168.png'
        and photo_type in {'image/png', 'png', 'png image', 'image png'}
        and parse_size(photo.get('size'), PHOTO_BYTES)
        and audio.get('filename') == 'field_voice_168.m4a'
        and audio_type in {'audio/m4a', 'audio/mp4', 'audio/x-m4a', 'm4a', 'm4a audio'}
        and parse_size(audio.get('size'), AUDIO_BYTES)
        and data.get('status') != 'failed'
    )
except Exception:
    ok = False
print('pass' if ok else 'fail')
